}

/**
 * KimGraf ML Module: Integration API
 *
 * ml_predictor + anomaly_detector + smart_alerts 통합
 */

pub use "./ml_predictor" as predictor
pub use "./anomaly_detector" as anomaly
pub use "./smart_alerts" as alerts

// ============================================================================
// Combined ML Pipeline
// ============================================================================

pub struct MLPipeline {
    metric_id: string,
    predictor: predictor.MLPredictor,
    detector: anomaly.AnomalyDetector,
    alert_engine: alerts.SmartAlertEngine,
    data_buffer: array<f32>,
    timestamp_buffer: array<u64>,
    buffer_max: u32,
    sample_count: u32,
    pipeline_ready: bool,
}

pub fn init_ml_pipeline(metric_id: string) -> MLPipeline {
    MLPipeline {
        metric_id: metric_id,
        predictor: predictor.init_ml_predictor(metric_id, 60),
        detector: anomaly.init_anomaly_detector(metric_id),
        alert_engine: alerts.init_smart_alert_engine(metric_id),
        data_buffer: [],
        timestamp_buffer: [],
        buffer_max: 1440,       // 24 hours @ 1-min samples
        sample_count: 0,
        pipeline_ready: false,
    }
}

pub struct PipelineResult {
    prediction: predictor.PredictionResult,
    anomaly_result: anomaly.AnomalyResult,
    should_alert: bool,
    alert_reason: string,
    confidence: f32,
}

pub fn process_sample(
    pipeline: MLPipeline,
    value: f32,
    timestamp_ms: u64
) -> tuple<MLPipeline, PipelineResult> {
    // Update data buffers
    new_data: array<f32> = pipeline.data_buffer
    new_ts: array<u64> = pipeline.timestamp_buffer

    new_data = append(new_data, value)
    new_ts = append(new_ts, timestamp_ms)

    // Trim if over max
    if len(new_data) > pipeline.buffer_max {
        trimmed_d: array<f32> = []
        trimmed_t: array<u64> = []
        start: u32 = len(new_data) - pipeline.buffer_max
        k: u32 = start
        while k < len(new_data) {
            trimmed_d = append(trimmed_d, new_data[k])
            trimmed_t = append(trimmed_t, new_ts[k])
            k = k + 1
        }
        new_data = trimmed_d
        new_ts = trimmed_t
    }

    new_count: u32 = pipeline.sample_count + 1

    // Train/update predictor periodically (every 60 samples or if needed)
    new_predictor: predictor.MLPredictor = pipeline.predictor
    if new_count % 60 == 0 || predictor.needs_retraining(pipeline.predictor, timestamp_ms) {
        new_predictor = predictor.train_predictor(pipeline.predictor, new_data, timestamp_ms)
    }

    // Update anomaly detector
    new_detector: anomaly.AnomalyDetector = anomaly.update_detector(
        pipeline.detector, value, timestamp_ms
    )

    // Fit isolation forest if enough data (every 500 samples)
    if new_count % 500 == 0 && len(new_data) >= 100 {
        new_detector = anomaly.fit_isolation(new_detector, new_data, new_count)
    }

    // Generate prediction
    t: u32 = new_count
    prediction: predictor.PredictionResult = predictor.predict_next(new_predictor, t)

    // Detect anomaly
    anomaly_result: anomaly.AnomalyResult = anomaly.detect_anomaly(new_detector, value)

    // Alert decision
    should_alert: bool = anomaly_result.is_anomaly
    alert_reason: string = ""
    if should_alert {
        alert_reason = "anomaly_detected:" + anomaly_result.severity
    }

    // Confidence = average of predictor accuracy + anomaly detector confidence
    combined_confidence: f32 = (prediction.confidence + anomaly_result.confidence) / 2.0

    // Determine if pipeline is ready (enough data)
    is_ready: bool = new_count >= 100

    new_pipeline: MLPipeline = MLPipeline {
        metric_id: pipeline.metric_id,
        predictor: new_predictor,
        detector: new_detector,
        alert_engine: pipeline.alert_engine,
        data_buffer: new_data,
        timestamp_buffer: new_ts,
        buffer_max: pipeline.buffer_max,
        sample_count: new_count,
        pipeline_ready: is_ready,
    }

    result: PipelineResult = PipelineResult {
        prediction: prediction,
        anomaly_result: anomaly_result,
        should_alert: should_alert,
        alert_reason: alert_reason,
        confidence: combined_confidence,
    }

    return (new_pipeline, result)
}

// ============================================================================
// Pipeline Health Check
// ============================================================================

pub struct PipelineHealth {
    metric_id: string,
    is_ready: bool,
    predictor_trained: bool,
    detector_calibrated: bool,
    sample_count: u32,
    anomaly_rate: f32,
    false_alarm_rate: f32,
    predictor_accuracy: f32,
}

pub fn get_pipeline_health(pipeline: MLPipeline) -> PipelineHealth {
    fp_rate: f32 = anomaly.get_false_positive_rate(pipeline.detector)
    accuracy: f32 = anomaly.get_detection_accuracy(pipeline.detector)

    anomaly_rate: f32 = 0.0
    if pipeline.detector.detection_count > 0 {
        anomaly_rate = float(pipeline.detector.anomaly_count) / float(pipeline.detector.detection_count)
    }

    PipelineHealth {
        metric_id: pipeline.metric_id,
        is_ready: pipeline.pipeline_ready,
        predictor_trained: pipeline.predictor.trained,
        detector_calibrated: pipeline.detector.iqr.calibrated,
        sample_count: pipeline.sample_count,
        anomaly_rate: anomaly_rate,
        false_alarm_rate: fp_rate,
        predictor_accuracy: pipeline.predictor.accuracy_score,
    }
}

/**
 * FreeLang Monitoring Suite: False-Reporting-Blocker Module
 *
 * 거짓 알람 차단 시스템 통합 API
 *
 * 무관용 규칙 10개:
 *   R1: 거짓 알람 필터링 > 95%
 *   R2: 정상 알람 통과 > 99%
 *   R3: 처리 지연 < 100ms
 *   R4: 이상 탐지 정확도 > 99%
 *   R5: 메모리 < 100MB
 *   R6: 데이터 보존 30days
 *   R7: 스팸 탐지 99.9%
 *   R8: False positive < 0.1%
 *   R9: 추론 지연 < 10µs
 *   R10: 모델 업데이트 < 1hour
 */

pub use "./bayesian_filter" as bayesian
pub use "./time_series_analysis" as tsa

// ============================================================================
// False Reporting Blocker: Main System
// ============================================================================

pub struct FalseReportingBlocker {
    metric_id: string,
    bayesian: bayesian.BayesianFilter,
    pattern_analyzer: tsa.PatternAnalyzer,
    alert_context_buffer: array<bayesian.AlertContext>,
    total_processed: u32,
    total_suppressed: u32,
    total_passed: u32,
    false_suppressed: u32,     // Incorrectly suppressed (FP)
    false_passed: u32,         // Incorrectly passed (FN)
    last_model_update_ms: u64,
}

pub fn init_blocker(metric_id: string) -> FalseReportingBlocker {
    FalseReportingBlocker {
        metric_id: metric_id,
        bayesian: bayesian.init_bayesian_filter(),
        pattern_analyzer: tsa.init_pattern_analyzer(metric_id),
        alert_context_buffer: [],
        total_processed: 0,
        total_suppressed: 0,
        total_passed: 0,
        false_suppressed: 0,
        false_passed: 0,
        last_model_update_ms: 0,
    }
}

pub struct BlockerDecision {
    should_suppress: bool,
    confidence: f32,
    reason: string,
    classification: bayesian.ClassificationResult,
    pattern_score: tsa.PatternAlarmScore,
}

pub fn evaluate_alert(
    blocker: FalseReportingBlocker,
    alert: bayesian.AlertContext,
    features: bayesian.AlertFeatures,
    now_ms: u64
) -> tuple<FalseReportingBlocker, BlockerDecision> {
    // 1. Bayesian classification
    classification: bayesian.ClassificationResult = bayesian.classify(blocker.bayesian, features)

    // 2. Pattern-based scoring
    pattern_score: tsa.PatternAlarmScore = tsa.compute_pattern_alarm_score(
        blocker.pattern_analyzer, alert.value, alert.threshold
    )

    // 3. Combined decision
    combined_false_prob: f32 = classification.false_alarm_prob * 0.7 + pattern_score.score * 0.3

    should_suppress: bool = false
    reason: string = "passed"

    if combined_false_prob > 0.60 {
        should_suppress = true
        if combined_false_prob > 0.85 {
            reason = "high_confidence_false_alarm"
        } else {
            reason = "likely_false_alarm"
        }
    } else if classification.decision == "uncertain" {
        reason = "uncertain_pass"
    }

    // Update counters
    new_processed: u32 = blocker.total_processed + 1
    new_suppressed: u32 = blocker.total_suppressed
    new_passed: u32 = blocker.total_passed

    if should_suppress {
        new_suppressed = new_suppressed + 1
    } else {
        new_passed = new_passed + 1
    }

    // Update pattern analyzer
    new_analyzer: tsa.PatternAnalyzer = tsa.update_analyzer_windows(
        blocker.pattern_analyzer, alert.value, now_ms
    )

    // Periodically run analysis
    need_analysis: bool = false
    if new_processed % 100 == 0 {
        need_analysis = true
    }
    if need_analysis {
        new_analyzer = tsa.run_analysis(new_analyzer, now_ms)
    }

    // Update context buffer
    new_buffer: array<bayesian.AlertContext> = blocker.alert_context_buffer
    new_buffer = append(new_buffer, alert)
    if len(new_buffer) > 10000 {
        trimmed: array<bayesian.AlertContext> = []
        start: u32 = len(new_buffer) - 10000
        k: u32 = start
        while k < len(new_buffer) {
            trimmed = append(trimmed, new_buffer[k])
            k = k + 1
        }
        new_buffer = trimmed
    }

    new_blocker: FalseReportingBlocker = FalseReportingBlocker {
        metric_id: blocker.metric_id,
        bayesian: blocker.bayesian,
        pattern_analyzer: new_analyzer,
        alert_context_buffer: new_buffer,
        total_processed: new_processed,
        total_suppressed: new_suppressed,
        total_passed: new_passed,
        false_suppressed: blocker.false_suppressed,
        false_passed: blocker.false_passed,
        last_model_update_ms: blocker.last_model_update_ms,
    }

    decision: BlockerDecision = BlockerDecision {
        should_suppress: should_suppress,
        confidence: combined_false_prob,
        reason: reason,
        classification: classification,
        pattern_score: pattern_score,
    }

    return (new_blocker, decision)
}

// ============================================================================
// Feedback Learning (R10: model update < 1 hour)
// ============================================================================

pub fn record_feedback(
    blocker: FalseReportingBlocker,
    features: bayesian.AlertFeatures,
    was_false_alarm: bool,
    now_ms: u64
) -> FalseReportingBlocker {
    updated_bayesian: bayesian.BayesianFilter = bayesian.train_bayesian(
        blocker.bayesian, features, was_false_alarm
    )

    FalseReportingBlocker {
        metric_id: blocker.metric_id,
        bayesian: updated_bayesian,
        pattern_analyzer: blocker.pattern_analyzer,
        alert_context_buffer: blocker.alert_context_buffer,
        total_processed: blocker.total_processed,
        total_suppressed: blocker.total_suppressed,
        total_passed: blocker.total_passed,
        false_suppressed: blocker.false_suppressed,
        false_passed: blocker.false_passed,
        last_model_update_ms: now_ms,
    }
}

// ============================================================================
// Statistics
// ============================================================================

pub fn get_filter_rate(blocker: FalseReportingBlocker) -> f32 {
    if blocker.total_processed == 0 { return 0.0 }
    return float(blocker.total_suppressed) / float(blocker.total_processed)
}

pub fn get_pass_rate(blocker: FalseReportingBlocker) -> f32 {
    if blocker.total_processed == 0 { return 0.0 }
    return float(blocker.total_passed) / float(blocker.total_processed)
}

pub fn get_model_accuracy(blocker: FalseReportingBlocker) -> f32 {
    return bayesian.get_model_accuracy(blocker.bayesian)
}
